package main

import (
	"github.com/corentings/chess/v2"
	"strings"
	"testing"
)

func safetyMirror(t *testing.T, p *chess.Position, color bool) *chess.Position {
	t.Helper()
	rows := make([]string, 8)
	for rank := 7; rank >= 0; rank-- {
		empty := 0
		for file := 0; file < 8; file++ {
			s := chess.Square(rank*8 + 7 - file)
			if color {
				s = chess.Square((7-rank)*8 + file)
			}
			piece := p.Board().Piece(s)
			if piece == chess.NoPiece {
				empty++
				continue
			}
			if empty > 0 {
				rows[7-rank] += string(rune('0' + empty))
				empty = 0
			}
			if color {
				piece = chess.NewPiece(piece.Type(), piece.Color().Other())
			}
			rows[7-rank] += map[chess.Piece]string{chess.WhitePawn: "P", chess.BlackPawn: "p", chess.WhiteKnight: "N", chess.BlackKnight: "n", chess.WhiteBishop: "B", chess.BlackBishop: "b", chess.WhiteRook: "R", chess.BlackRook: "r", chess.WhiteQueen: "Q", chess.BlackQueen: "q", chess.WhiteKing: "K", chess.BlackKing: "k"}[piece]
		}
		if empty > 0 {
			rows[7-rank] += string(rune('0' + empty))
		}
	}
	turn := "w"
	if color {
		turn = "b"
	}
	return evalFEN(t, strings.Join(rows, "/")+" "+turn+" - - 0 1")
}
func TestPieceSafetyControls(t *testing.T) {
	cases := []struct {
		name, fen string
		want      int
	}{
		{"undefended knight", "3r3k/8/8/8/3N4/8/8/K7 w - - 0 1", -16},
		{"defended knight", "3r3k/8/8/8/3N4/2P5/8/K7 w - - 0 1", 0},
		{"blocked rook ray", "3r3k/8/3p4/8/3N4/8/8/K7 w - - 0 1", 0},
		{"defended pawn attack on queen", "7k/8/5p2/4p3/3Q4/8/8/K7 w - - 0 1", -48},
		{"defended pawn attack on rook", "7k/8/5p2/4p3/3R4/8/8/K7 w - - 0 1", -36},
		{"defended pawn attack on knight", "7k/8/5p2/4p3/3N4/8/8/K7 w - - 0 1", -24},
		{"pinned defender", "2r1r2k/8/8/8/4B3/2N5/1P6/2K5 w - - 0 1", -16},
		{"pinned attacker", "5k2/6p1/5n2/7Q/8/8/8/K4R2 w - - 0 1", 0},
		{"legal king defence", "3r3k/8/8/8/3N4/2K5/8/8 w - - 0 1", 0},
		{"illegal king recapture xray", "3r3k/8/8/8/3N4/2K5/8/3r4 w - - 0 1", -16},
		{"newly opened defender ray", "7k/8/3p1B2/4b1P1/3N4/8/8/K7 w - - 0 1", 0},
		{"safe unattacked piece", "7k/8/8/8/3N4/8/8/K7 w - - 0 1", 0},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			p := evalFEN(t, c.fen)
			for _, m := range []struct {
				p    *chess.Position
				side chess.Color
			}{{p, chess.White}, {safetyMirror(t, p, false), chess.White}, {safetyMirror(t, p, true), chess.Black}} {
				got := pieceSafety(m.p, m.side)
				if got != c.want {
					t.Errorf("%s: got %d want %d", m.p, got, c.want)
				}
				if got != -pieceSafety(m.p, m.side.Other()) {
					t.Fatal("perspective mismatch")
				}
			}
		})
	}
}
func TestSafetySummaryMatchesGeometry(t *testing.T) {
	for _, fen := range []string{chess.StartingPosition().String(), "r2q1b1r/ppp1k1pp/4pn2/6BQ/2p5/2N5/PP3PPP/R4RK1 b - - 5 13", "2r1r2k/8/8/8/4B3/2N5/1P6/2K5 w - - 0 1"} {
		p := evalFEN(t, fen)
		b, a, _ := safetySummary(p)
		for from, piece := range b.pieces {
			if piece == chess.NoPiece {
				continue
			}
			for to := 0; to < 64; to++ {
				got := a[piece.Color()][to]&(uint64(1)<<from) != 0
				if got != b.attacks(chess.Square(from), chess.Square(to)) {
					t.Fatalf("geometry mismatch %d -> %d", from, to)
				}
			}
		}
	}
}
func TestPieceSafetyCaptureAndSacrificeControls(t *testing.T) {
	// A loose piece en prise is resolved by existing quiescence. Do not deduct
	// its full material value again. Material values themselves stay unchanged.
	p := evalFEN(t, "3r3k/8/8/8/3N4/8/8/K7 b - - 0 1")
	if pieceSafety(p, chess.White) != -16 || materialScore(p, chess.White) != -200 {
		t.Fatal("exposure/material scale changed")
	}
	if q := quiescence(p, quiescenceDepth, -searchInfinity, searchInfinity); q < 450 {
		t.Fatalf("quiescence did not settle capture: %d", q)
	}
	// A protected queen delivers mate. Root choice is free;
	// require a legal mate, not one named reference move.
	p = evalFEN(t, "7k/5Q2/5K2/8/8/8/8/8 w - - 0 1")
	w := searcher{}
	best, score, ok := w.root(p, orderedMoves(p), 3)
	if !ok || score < mateBound {
		t.Fatalf("missed forcing mate: %v %d", best, score)
	}
	for _, s := range best {
		for _, m := range p.ValidMoves() {
			if m.String() == s && p.Update(&m).Status() != chess.Checkmate {
				t.Fatalf("selected nonmate %s", s)
			}
		}
	}
}
func BenchmarkStaticPieceSafety(b *testing.B) {
	p := chess.StartingPosition()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		staticScore(p, chess.White)
	}
}

// The full root is unrestricted in this smothered-mate position. The forcing
// line Qg8+ Rxg8 Nf7# offers a queen; recognizing exposure must not suppress it.
func TestPieceSafetyQueenSacrifice(t *testing.T) {
	p := evalFEN(t, "5r1k/6pp/7N/8/2Q5/8/8/K7 w - - 0 1")
	w := searcher{}
	best, score, ok := w.root(p, orderedMoves(p), 3)
	if !ok || len(best) == 0 || score < mateScore-3 {
		t.Fatalf("lost forcing mate in queen-sacrifice control: %v %d", best, score)
	}
}

